<script setup>
import { computed, defineAsyncComponent } from 'vue'
import DisclosurePanel from './DisclosurePanel.vue'
import { useResource } from './useResource.js'
import { comparisonInterval } from './resultIntervals.js'
import { useSectionFocus } from './useSectionFocus.js'
const props=defineProps({section:String})
useSectionFocus(()=>props.section,'results-')
defineEmits(['show-case'])
const V04Results=defineAsyncComponent(()=>import('./V04Results.vue'))
const V05Results=defineAsyncComponent(()=>import('./V05Results.vue'))
const BenchmarkOverview=defineAsyncComponent(()=>import('./BenchmarkOverview.vue'))
const ResearchDetails=defineAsyncComponent(()=>import('./ResearchDetails.vue'))
const {data:v04,error:e04,loading:l04,reload:r04}=useResource('/api/results_v04')
const {data:v05,error:e05,loading:l05,reload:r05}=useResource('/api/results_v05')
const {data:intervals}=useResource('/api/benchmarks')
const interval=(study,key)=>comparisonInterval(intervals.value,study==='v04'?'v04_test':'v05_cv',key)
const n=v=>v==null?'–':Number(v).toLocaleString('de-AT',{minimumFractionDigits:3,maximumFractionDigits:3})
const signed=v=>(v>0?'+':'')+n(v)
const labels={static:'Gelände allein',temporal:'Wetter allein',combined:'Gelände + Wetter'}
const studies=computed(()=>[
  {id:'v04',tag:'V0.4 · einmal ausgewerteter Test',title:'Ähnliche Hänge unterscheiden.',description:'Fünf topographisch ähnliche Vergleichshänge pro Ereignis. Der versiegelte Test wurde genau einmal ausgewertet.',data:v04.value,error:e04.value,loading:l04.value,reload:r04,events:v04.value?.counts.partition.sealed_test.events,units:v04.value?.counts.partition.sealed_test.units,primary:v04.value?.test.primary,rows:Object.entries(labels).map(([key,label])=>({key,label,value:v04.value?.test.results['conditional_logit/'+key]?.local_auc_weighted})),delta:v04.value?.test.primary.combined_minus_static},
  {id:'v05',tag:'V0.5 · neueste Untersuchung · explorativ',title:'Den lokalen Hintergrund vergleichen.',description:'Zehn ungematchte Umgebungshänge pro Ereignis. Kreuzvalidierung auf bereits bekannten Ereignissen: Modelle werden wiederholt an zurückgehaltenen Gruppen geprüft; benachbarte Trainingspunkte bleiben ausgeschlossen.',data:v05.value,error:e05.value,loading:l05.value,reload:r05,events:v05.value?.cohort.events,units:v05.value?.cohort.units,primary:v05.value?.primary,rows:Object.entries(labels).map(([key,label])=>({key,label,value:v05.value?.purged['conditional_logit/'+key]?.local_auc_units})),delta:v05.value?.primary.combined_minus_static_rep1_bootstrap}
])
</script>
<template>
  <section class="page-intro results-intro"><p class="eyebrow">03 / Ergebnisse</p><h1>Das Gelände liefert Signal.<br><span>Der Wetternutzen bleibt offen.</span></h1><p>PreSlide kann betroffene Hänge in diesen Vergleichen teilweise unterscheiden. Ein belastbarer Zusatznutzen des Wetters gegenüber dem Gelände allein ist bisher nicht belegt.</p></section>
  <aside class="context-strip"><span class="context-label">Zwei unterschiedliche Fragen</span><p>V0.5 zeigt höhere Kennzahlen bei <strong>leichteren Vergleichshängen</strong>. Das ist kein direkter Leistungsfortschritt gegenüber dem V0.4-Test. Beide Untersuchungen sind abgeschlossen.</p></aside>
  <section class="metric-explanation"><h2>Wie liest man die lokale AUC?</h2><p>Sie misst, wie oft der betroffene Hang höher eingeordnet wird als ein Vergleichshang seiner Gruppe. <strong>0,5 entspricht Zufall, 1 einer perfekten Rangfolge.</strong> Jede Abhängigkeitseinheit erhält das gleiche Gewicht. Der Wert ist keine Rutschungswahrscheinlichkeit.</p><p class="muted">„Gelände“ umfasst hier auch Landbedeckung und Geologie; „Wetter“ schließt Schnee ein. Gezeigt wird jeweils die bedingte logistische Regression, das vorab festgelegte Hauptmodell. Es vergleicht Hänge innerhalb ihrer jeweiligen Gruppe.</p></section>
  <section v-for="s in studies" :key="s.id" class="study-result" :aria-label="s.tag">
    <div class="study-heading"><span class="study-label">{{s.tag}}</span><span v-if="s.data" class="study-sample">{{s.events}} Ereignisse · <b>{{s.units}} Abhängigkeitseinheiten</b></span></div>
    <h2>{{s.title}}</h2><p class="study-description">{{s.description}}</p>
    <p v-if="s.loading" role="status" class="loading">Gespeicherte Ergebnisse werden geladen …</p><div v-else-if="s.error" role="alert" class="error"><p>{{s.error}}</p><button @click="s.reload">Erneut laden</button></div>
    <template v-else-if="s.data"><div class="result-layout"><div class="comparison-chart"><div class="chart-scale"><span>Lokale AUC</span><span>0,5 · Zufall</span><span>1,0</span></div><div v-for="row in s.rows" :key="row.key" class="comparison-row" :class="row.key"><div class="comparison-label"><span>{{row.label}}</span><strong>{{n(row.value)}}</strong></div><div class="comparison-track"><span :style="{width:row.value*100+'%'}"></span><i class="reference-line"></i></div><small v-if="interval(s.id,row.key)" class="bar-interval">{{interval(s.id,row.key).label}}: {{n(interval(s.id,row.key).range[0])}}–{{n(interval(s.id,row.key).range[1])}}</small><small v-else class="bar-interval">Intervall für diese Variante derzeit nicht verfügbar.</small></div><p class="chart-caption">{{s.id==='v04'?'Gespeicherter Testwert · jede Einheit gleich gewichtet':'Median aus fünf Wiederholungen derselben Daten · keine fünf unabhängigen Studien'}}</p></div><aside class="uncertainty-panel"><template v-if="s.id==='v04'"><p class="eyebrow">Kombiniertes Modell</p><strong class="interval">{{n(s.primary.ci95[0])}}–{{n(s.primary.ci95[1])}}</strong><p>95-%-Unsicherheitsintervall durch Wiederziehen ganzer Abhängigkeitseinheiten.</p><p>Zufallsreferenz: {{n(s.primary.chance)}}<br>95-%-Grenze zufälliger Rangfolgen: {{n(s.primary.random_rank_null_q95)}}<br>p gegen Zufall: {{n(s.data.test.results['conditional_logit/combined'].p_upper_vs_random_rank)}}</p></template><template v-else><p class="eyebrow">Kombiniertes Modell</p><strong class="interval">{{n(s.primary.ci95_rep1[0])}}–{{n(s.primary.ci95_rep1[1])}}</strong><p>95-%-Unsicherheitsintervall der <strong>ersten Wiederholung</strong>, durch Wiederziehen ganzer Abhängigkeitseinheiten.</p><p>Spanne der fünf Wiederholungen: {{n(s.primary.range[0])}}–{{n(s.primary.range[1])}}. Sie ist kein Konfidenzintervall.</p><p>Zufall: {{n(s.primary.chance)}} · einfache Neigungsregel: {{n(s.primary.slope_rule)}}</p></template></aside></div>
    <div class="weather-finding"><div><span>Bringt das Wetter zusätzlich etwas?</span><h3>Kein belegter Zusatznutzen.</h3></div><div><strong>{{signed(s.delta.mean)}}</strong><p>Gelände + Wetter minus Gelände<br>95-%-Intervall: {{signed(s.delta.ci95[0])}} bis {{signed(s.delta.ci95[1])}}<span v-if="s.id==='v05'"> · erste Wiederholung</span></p></div></div><p class="plain-note">Das gepaarte Intervall schließt null ein. Ein Vorteil ist damit nicht abgesichert. Das beweist nicht, dass Wetter keinen Einfluss auf Hangrutschungen hat.</p></template>
  </section>
  <section class="limitations"><p class="eyebrow">Was die Aussage begrenzt</p><h2>Ein Ergebnis mit Kontext.</h2><div class="three-columns"><article><h3>Wenige unabhängige Episoden</h3><p>Ein großer Sturm kann viele Ereignisse liefern. Im V0.4-Test stammen 243 der 300 Ereignisse aus der Stanz-Episode. Die Gewichtung nach Einheiten begrenzt diese Dominanz.</p></article><article><h3>Ein möglicher Meldeeffekt</h3><p>Das Modell nutzt Geländeform und Landbedeckung. Offenland und Siedlungsnähe können auch beeinflussen, wo Ereignisse entdeckt und dokumentiert werden.</p></article><article><h3>Keine Gefahrenprognose</h3><p>Die Resultate gelten für diese retrospektiven Vergleiche. Sie belegen weder geografische Übertragbarkeit noch eine reale Rutschungswahrscheinlichkeit.</p></article></div><p class="plain-note" v-if="v04">Zur Einordnung der Stanz-Dominanz: Bei gleicher Gewichtung aller Ereignisse beträgt die kombinierte lokale AUC {{n(v04.test.results['conditional_logit/combined'].local_auc_events)}} statt {{n(v04.test.primary.value)}} bei gleicher Gewichtung der {{v04.counts.partition.sealed_test.units}} Einheiten. Das ist eine ergänzende Sicht auf denselben Test.</p></section>
  <div class="deep-dives"><p class="eyebrow">Weiter erkunden</p><DisclosurePanel id="results-v04" title="V0.4: alle Modelle und Testdetails" subtitle="Gespeicherter versiegelter Test und getrennte Entwicklungsauswertung" :open="section==='v04'"><V04Results/></DisclosurePanel><DisclosurePanel id="results-v05" title="V0.5: Karten, Vergleichshänge und Modellmerkmale" subtitle="Reale Beispiele, alle Ereignisse und explorative Diagnosen" :open="section==='v05'"><V05Results/></DisclosurePanel><DisclosurePanel id="results-vergleich" title="Alle Untersuchungen im Vergleich" subtitle="V0 bis V0.5 · unterschiedliche Designs bleiben getrennt" :open="section==='vergleich'"><BenchmarkOverview/></DisclosurePanel><DisclosurePanel id="results-historie" title="Frühere Untersuchungen und Ereignis-Explorer" subtitle="Historische Baseline V0–V0.3 · Stabilität, Zufallsreferenz und Einzelfälle" :open="section==='historie'"><ResearchDetails mode="history" @show-case="$emit('show-case',$event)"/></DisclosurePanel></div>
  <a class="next-page" href="#/vorgehen/beispiel"><div><span>Selbst erkunden</span><strong>Die Forschung<br>an einem Hang verstehen.</strong></div><svg viewBox="0 0 48 48" aria-hidden="true"><path d="M8 24h32M26 10l14 14-14 14"/></svg></a>
</template>
